    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity", () => {
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("removes product when updating quantity to 0", () => {
    cart.add(productA, 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    // Confirm it's truly removed
    expect(cart.remove("a")).toBe(false);
  });

  it("throws on updateQuantity for unknown product", () => {
    expect(() => cart.updateQuantity("nope", 5)).toThrow(
      "Product nope is not in the cart",
    );
  });

  it("throws on negative quantity in updateQuantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("throws on non-integer quantity in updateQuantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clears all items", () => {
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copies", () => {
    cart.add(productA, 2);
    const snap = cart.snapshot();
    // mutate snapshot
    (snap[0] as { quantity: number }).quantity = 99;
    // cart should be unaffected
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3); // 3000
    cart.add(productB, 2); // 5000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(8000);
  });

  it("returns all-zero totals for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount → tax on discounted subtotal → shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(2000),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(600),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };

    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(productA, 10); // subtotal = 10000

    const totals = cart.totals();

    // Discount called with subtotal
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(10000);
    expect(totals.discountCents).toBe(2000);

    // Tax called with discounted subtotal = 10000 - 2000 = 8000
    expect(tax.computeTaxCents).toHaveBeenCalledWith(8000, "US-CA");
    expect(totals.taxCents).toBe(600);

    // Shipping called with lines and discounted subtotal
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      8000,
    );
    expect(totals.shippingCents).toBe(500);

    // Total = discounted subtotal + tax + shipping = 8000 + 600 + 500
    expect(totals.totalCents).toBe(9100);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount returns more than subtotal
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to US region when not specified", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });
});

describe("Cart — async checkout()", () => {
  it("returns totals and lines for empty collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(productA, 2); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });

    // subtotal = 1500 * 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
      expect(invErr.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available but qty < requested)", async () => {
    const cart = new Cart();
    cart.add(productA, 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("passes inventory check when available and qty sufficient", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider to compute tax", async () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1); // subtotal = 1000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn<(region: string) => Promise<number>>().mockResolvedValue(0.2),
    };
    const result = await cart.checkout({ asyncTaxProvider });

    // Tax = floor(1000 * 0.2) = 200
    expect(result.totals.taxCents).toBe(200);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    // sync tax calculator should NOT have been used for tax computation
    // (but note it's still in the Cart — the async path replaces it)
  });

  it("composes priceFetcher + asyncTaxProvider + discount + shipping", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US",
    });
    cart.add(productA, 2); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>().mockResolvedValue(2000),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn<(region: string) => Promise<number>>().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });

    // subtotal = 2000 * 2 = 4000
    expect(result.totals.subtotalCents).toBe(4000);
    // discount = 500 (clamped to [0, 4000])
    expect(result.totals.discountCents).toBe(500);
    // discounted = 4000 - 500 = 3500
    // tax = floor(3500 * 0.1) = 350
    expect(result.totals.taxCents).toBe(350);
    // shipping = 300
    expect(result.totals.shippingCents).toBe(300);
    // total = 3500 + 350 + 300 = 4150
    expect(result.totals.totalCents).toBe(4150);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API error")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price API error",
    );
  });

  it("uses default reason message when inventoryChecker gives no reason", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.message).toContain("insufficient stock");
      expect(invErr.message).toContain("a");
    }
  });

  it("checks inventory for all lines and first denial wins", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({
          available: false,
          reason: "discontinued",
        }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Second product fails
      expect((err as InventoryError).productId).toBe("b");
      expect((err as InventoryError).message).toBe("discontinued");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "below zero"],
      [101, "above 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
      [-Infinity, "-Infinity"],
    ])("rejects percent=%s (%s)", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts percent=%i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [50, 1000, 500],
      [100, 1000, 1000],
      [0, 1000, 0],
      [33, 100, 33],
      // Rounding: 10% of 999 = 99.9 → floors to 99
      [10, 999, 99],
      [15, 1001, 150], // 150.15 → 150
    ])("%i%% of %i cents = %i", (pct, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(pct);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [10.5, "non-integer"],
      [NaN, "NaN"],
    ])("rejects amountCents=%s (%s)", (amt) => {
      expect(() => new FixedAmountDiscountPolicy(amt)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when equal to fixed amount", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent policy results against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Both see 1000: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("sum can exceed subtotal (clamped by Cart, not here)", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(800);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Both see 1000: min(800,1000) + min(800,1000) = 1600
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0 so this should be well-behaved
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies each policy to the remaining subtotal", () => {
      // 10% of 1000 = 100, then 10% of 900 = 90; total = 190
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      // FixedAmount(200) first: 200, then 10% of 800 = 80; total = 280
      const fixed = new FixedAmountDiscountPolicy(200);
      const pct = new PercentageDiscountPolicy(10);
      const compositeA = new CompositeDiscountPolicy([fixed, pct], "chain");
      expect(compositeA.computeDiscountCents(1000)).toBe(280);

      // Percentage(10) first: 100, then FixedAmount(200) on 900 = 200; total = 300
      const compositeB = new CompositeDiscountPolicy([pct, fixed], "chain");
      expect(compositeB.computeDiscountCents(1000)).toBe(300);
    });

    it("caps each step at remaining subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(800);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // First: min(800, 1000) = 800, remaining = 200
      // Second: min(800, 200) = 200, remaining = 0; total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when mode not specified", () => {
    const p1 = new FixedAmountDiscountPolicy(100);
    const p2 = new FixedAmountDiscountPolicy(200);
    const composite = new CompositeDiscountPolicy([p1, p2]);
    // sum mode: 100 + 200 = 300
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

