    expect(result[0]!.product.weightGrams).toBe(200);
    expect(result[0]!.product.currency).toBe("EUR");
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>().mockResolvedValue(-1),
    };
    await expect(
      refreshPrices([makeLine("a", 100, 1)], fetcher),
