    cart.add(productA, 1); // subtotal = 1000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn<(region: string) => Promise<number>>().mockResolvedValue(0.2),
    };
    const result = await cart.checkout({ asyncTaxProvider });

    // Tax = floor(1000 * 0.2) = 200
    expect(result.totals.taxCents).toBe(200);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    // sync tax calculator should NOT have been used for tax computation
    // (but note it's still in the Cart — the async path replaces it)
  });

  it("composes priceFetcher + asyncTaxProvider + discount + shipping", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
