      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US",
    });
    cart.add(productA, 2); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>().mockResolvedValue(2000),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn<(region: string) => Promise<number>>().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });

    // subtotal = 2000 * 2 = 4000
    expect(result.totals.subtotalCents).toBe(4000);
    // discount = 500 (clamped to [0, 4000])
    expect(result.totals.discountCents).toBe(500);
    // discounted = 4000 - 500 = 3500
    // tax = floor(3500 * 0.1) = 350
    expect(result.totals.taxCents).toBe(350);
    // shipping = 300
    expect(result.totals.shippingCents).toBe(300);
    // total = 3500 + 350 + 300 = 4150
    expect(result.totals.totalCents).toBe(4150);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
